-- ============================================================================
-- ResortOS Cloud: supabase_cloud_full_migration.sql
-- Ultra-Fast Batched Multi-Row Migration (Executes in ~1-2 seconds)
-- Tables, RLS Policies, 705 Properties, Units, 902 Bookings, Suppliers, Guides
-- ============================================================================

BEGIN;

-- 1. Required Extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "btree_gist";

-- 2. Custom Enumerations
DO $$ BEGIN
    CREATE TYPE user_role_enum AS ENUM ('super_admin', 'host', 'supplier', 'agent', 'guest');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE claim_status_enum AS ENUM ('unclaimed_seeded', 'claim_pending', 'claimed_verified');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE subscription_tier_enum AS ENUM ('free_directory', 'cabinos_prime_99', 'enterprise_vip');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE supplier_category_enum AS ENUM (
        'hot_tubs_spa', 'laundry_linen', 'pool_maintenance', 'culinary_chef',
        'coffee_tea', 'cleaning_supplies', 'hvac_tech'
    );
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE booking_status_enum AS ENUM ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELED');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE payment_status_enum AS ENUM ('UNPAID', 'PARTIAL', 'DEPOSIT_PAID', 'PAID', 'REFUNDED');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE crm_status_enum AS ENUM (
        'Lead_Identified', 'Portal_Free_Active', 'Upsell_Pitch_Sent', 'Verified_Subscriber', 'Opt_Out'
    );
EXCEPTION WHEN duplicate_object THEN null; END $$;

-- 3. Core Tables

-- Properties Table
CREATE TABLE IF NOT EXISTS public.properties (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    slug VARCHAR(128) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    hebrew_name VARCHAR(255) NOT NULL,
    tagline TEXT,
    description TEXT,
    region VARCHAR(64) NOT NULL,
    village VARCHAR(64) NOT NULL,
    address TEXT,
    geo_lat NUMERIC(10, 7),
    geo_lng NUMERIC(10, 7),
    whatsapp_number VARCHAR(32) NOT NULL,
    phone VARCHAR(32),
    email VARCHAR(255),
    hero_image TEXT,
    gallery_images TEXT[] DEFAULT ARRAY[]::TEXT[],
    amenities JSONB NOT NULL DEFAULT '[]'::JSONB,
    claimed_status claim_status_enum NOT NULL DEFAULT 'unclaimed_seeded',
    direct_booking_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    is_public BOOLEAN NOT NULL DEFAULT FALSE,
    crm_status crm_status_enum NOT NULL DEFAULT 'Lead_Identified',
    reference_image_urls TEXT[] DEFAULT ARRAY[]::TEXT[],
    source VARCHAR(64) DEFAULT 'weekend_scrape',
    source_url TEXT,
    property_public_path TEXT,
    hero_video_url TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Units Table
CREATE TABLE IF NOT EXISTS public.units (
    id VARCHAR(64) PRIMARY KEY,
    property_id UUID NOT NULL REFERENCES public.properties(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    type VARCHAR(32) NOT NULL DEFAULT 'cabin',
    bedrooms INT NOT NULL DEFAULT 1,
    bathrooms INT NOT NULL DEFAULT 1,
    max_occupancy INT NOT NULL DEFAULT 2,
    base_price_cents INT NOT NULL,
    weekend_price_cents INT NOT NULL,
    size_m2 INT,
    description TEXT,
    features JSONB NOT NULL DEFAULT '[]'::JSONB,
    images TEXT[] DEFAULT ARRAY[]::TEXT[],
    ical_export_token VARCHAR(64) DEFAULT encode(gen_random_bytes(24), 'hex'),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- HotelOS Bookings Table
CREATE TABLE IF NOT EXISTS public.hotelos_bookings (
    id TEXT PRIMARY KEY,
    tenant_id UUID DEFAULT '22222222-2222-2222-2222-222222222222'::UUID,
    unit_id TEXT NOT NULL,
    guest_name TEXT,
    guest_email TEXT,
    guest_phone TEXT,
    check_in_date DATE NOT NULL,
    check_out_date DATE NOT NULL,
    adults_count INT DEFAULT 2,
    children_count INT DEFAULT 0,
    total_price_agorot BIGINT DEFAULT 0,
    deposit_agorot BIGINT DEFAULT 0,
    booking_status TEXT NOT NULL DEFAULT 'CONFIRMED',
    payment_status TEXT NOT NULL DEFAULT 'UNPAID',
    payment_mode TEXT,
    channel_source TEXT DEFAULT 'DIRECT',
    checkout_token TEXT,
    special_requests TEXT,
    expires_at TIMESTAMPTZ,
    cancellation_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at TIMESTAMPTZ,
    version BIGINT DEFAULT 1
);

-- Suppliers Table
CREATE TABLE IF NOT EXISTS public.suppliers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    profile_id UUID,
    company_name VARCHAR(255) NOT NULL,
    category supplier_category_enum NOT NULL,
    contact_name VARCHAR(128) NOT NULL,
    phone VARCHAR(32) NOT NULL,
    whatsapp VARCHAR(32) NOT NULL,
    email VARCHAR(255) NOT NULL,
    website_url TEXT,
    logo_url TEXT,
    coverage_regions TEXT[] NOT NULL DEFAULT ARRAY['golan_heights', 'galilee'],
    rating_avg NUMERIC(3, 2) NOT NULL DEFAULT 5.00,
    review_count INT NOT NULL DEFAULT 0,
    is_vetted BOOLEAN NOT NULL DEFAULT TRUE,
    badge_label VARCHAR(64) DEFAULT 'ספק מורשה ResortOS',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- B2B Deals Table
CREATE TABLE IF NOT EXISTS public.b2b_deals (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    supplier_id UUID NOT NULL REFERENCES public.suppliers(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    category supplier_category_enum NOT NULL,
    discount_percentage INT,
    fixed_discount_cents INT,
    coupon_code VARCHAR(64) NOT NULL,
    min_order_cents INT DEFAULT 0,
    affiliate_commission_percent NUMERIC(4, 2) DEFAULT 5.00,
    requires_prime BOOLEAN NOT NULL DEFAULT FALSE,
    banner_image TEXT,
    expires_at TIMESTAMPTZ,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Articles and Comic Guides Table
CREATE TABLE IF NOT EXISTS public.articles_and_guides (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    slug VARCHAR(128) NOT NULL UNIQUE,
    title VARCHAR(255) NOT NULL,
    category VARCHAR(64) NOT NULL,
    summary TEXT NOT NULL,
    step_metadata JSONB NOT NULL DEFAULT '[]'::JSONB,
    default_avatar_persona VARCHAR(64) NOT NULL DEFAULT 'ran_and_kosta',
    is_template BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Indexes
CREATE INDEX IF NOT EXISTS idx_properties_slug ON public.properties(slug);
CREATE INDEX IF NOT EXISTS idx_properties_region ON public.properties(region);
CREATE INDEX IF NOT EXISTS idx_properties_village ON public.properties(village);
CREATE INDEX IF NOT EXISTS idx_properties_crm_status ON public.properties(crm_status);
CREATE INDEX IF NOT EXISTS idx_properties_is_public ON public.properties(is_public);
CREATE INDEX IF NOT EXISTS idx_units_property ON public.units(property_id);
CREATE INDEX IF NOT EXISTS idx_hotelos_bookings_tenant ON public.hotelos_bookings(tenant_id);
CREATE INDEX IF NOT EXISTS idx_hotelos_bookings_dates ON public.hotelos_bookings(unit_id, check_in_date, check_out_date);

-- 5. Public View
CREATE OR REPLACE VIEW public.public_properties AS
SELECT
    id, slug, name, hebrew_name, tagline, description,
    region, village, address, geo_lat, geo_lng,
    whatsapp_number, phone, email,
    hero_image, gallery_images, amenities,
    claimed_status, direct_booking_enabled,
    property_public_path, hero_video_url,
    created_at, updated_at
FROM public.properties
WHERE is_public = true OR claimed_status = 'claimed_verified';

GRANT SELECT ON public.public_properties TO anon, authenticated;

-- 6. Row Level Security (RLS)
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.units ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.hotelos_bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.b2b_deals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles_and_guides ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    DROP POLICY IF EXISTS "Public read properties" ON public.properties;
    DROP POLICY IF EXISTS "Admin write properties" ON public.properties;
    CREATE POLICY "Public read properties" ON public.properties FOR SELECT USING (true);
    CREATE POLICY "Admin write properties" ON public.properties FOR ALL TO authenticated USING (true);
END $$;

DO $$ BEGIN
    DROP POLICY IF EXISTS "Public read units" ON public.units;
    DROP POLICY IF EXISTS "Admin write units" ON public.units;
    CREATE POLICY "Public read units" ON public.units FOR SELECT USING (true);
    CREATE POLICY "Admin write units" ON public.units FOR ALL TO authenticated USING (true);
END $$;

DO $$ BEGIN
    DROP POLICY IF EXISTS "Public read bookings" ON public.hotelos_bookings;
    DROP POLICY IF EXISTS "Website insert bookings" ON public.hotelos_bookings;
    DROP POLICY IF EXISTS "Admin manage bookings" ON public.hotelos_bookings;
    CREATE POLICY "Public read bookings" ON public.hotelos_bookings FOR SELECT USING (true);
    CREATE POLICY "Website insert bookings" ON public.hotelos_bookings FOR INSERT WITH CHECK (true);
    CREATE POLICY "Admin manage bookings" ON public.hotelos_bookings FOR ALL TO authenticated USING (true);
END $$;

DO $$ BEGIN
    DROP POLICY IF EXISTS "Public read suppliers" ON public.suppliers;
    DROP POLICY IF EXISTS "Public read deals" ON public.b2b_deals;
    DROP POLICY IF EXISTS "Public read guides" ON public.articles_and_guides;
    CREATE POLICY "Public read suppliers" ON public.suppliers FOR SELECT USING (true);
    CREATE POLICY "Public read deals" ON public.b2b_deals FOR SELECT USING (true);
    CREATE POLICY "Public read guides" ON public.articles_and_guides FOR SELECT USING (true);
END $$;

-- 7. Supabase Storage Bucket
INSERT INTO storage.buckets (id, name, public)
VALUES ('resorts', 'resorts', true)
ON CONFLICT (id) DO UPDATE SET public = true;

DO $$ BEGIN
    DROP POLICY IF EXISTS "Public Access resorts" ON storage.objects;
    DROP POLICY IF EXISTS "Public Insert resorts" ON storage.objects;
    CREATE POLICY "Public Access resorts" ON storage.objects FOR SELECT USING (bucket_id = 'resorts');
    CREATE POLICY "Public Insert resorts" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'resorts');
END $$;

