-- 8.3 902 Bookings, Suppliers, Deals & Guides
INSERT INTO public.articles_and_guides VALUES
('5355cb7e-1aa6-40eb-a6db-c0b499a70a60', 'hot-tub-operation', 'הפעלת ג׳קוזי ספא ובקרת טמפרטורה', 'hot_tubs_spa', 'מדריך מצויר צעד-אחר-צעד לאורח להפעלה נכונה, הפעלת ג׳טים, שמירה על חום המים ומניעת תקלות.', '[{"step": 1, "title": "הסרת הכיסוי התרמי", "proTip": "אל תמשכו את הכיסוי בכוח מרצועות הצד – אחיזה במרכז הכיסוי מאריכה את חיי התפרים.", "instructions": "שחררו את קליפסי הנעילה משני צידי הג׳קוזי וקפלו את הכיסוי התרמי לחצי לאחור בזהירות.", "illustrationUrl": "https://images.unsplash.com/photo-1584622650111-993a426fbf0a?auto=format&fit=crop&w=600&q=80"}, {"step": 2, "title": "בדיקת טמפרטורה במסך הדיגיטלי", "proTip": "המים שומרים על חום מושלם כל עוד הכיסוי מונח. חימום מלא של מעלה אחת לוקח כ-20 דקות.", "instructions": "הטמפרטורה המומלצת מכוונת מראש ל-38°C. להעלאה או הורדה לחצו על חיצי הטמפרטורה (חכו 3 שניות לאישור).", "illustrationUrl": "https://images.unsplash.com/photo-1507652313519-d4e9174996dd?auto=format&fit=crop&w=600&q=80"}, {"step": 3, "title": "הפעלת ג׳טים וזרמי מסאז׳", "proTip": "המשאבה נכבית אוטומטית לאחר 20 דקות רצופות מטעמי בטיחות וחיסכון באנרגיה.", "instructions": "לחצו פעם אחת על כפתור JETS 1 להפעלת זרם נעים, ופעם נוספת לעוצמת מסאז׳ מלאה.", "illustrationUrl": "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=600&q=80"}, {"step": 4, "title": "יציאה והחזרת הכיסוי התרמי", "proTip": "כיסוי סגור מונע חדירת עלים ושומר על צלילות המים לכל אורך החופשה שלכם.", "instructions": "בסיום הרחצה, כסו את הג׳קוזי בחזרה לחלוטין. שמירת הכיסוי מבטיחה מים רותחים וצלולים לטבילה הבאה.", "illustrationUrl": "https://images.unsplash.com/photo-1584622650111-993a426fbf0a?auto=format&fit=crop&w=600&q=80"}]', 'ran_and_kosta', true, '2026-09-10 05:57:14.12849+00'),
('dbe89e72-04f3-4017-b5da-f1f316a2a686', 'specialty-coffee-hotswap', 'תפעול מכונת נספרסו והחלפת קפסולות', 'coffee_tea', 'מדריך מהיר להכנת אספרסו ולונגו מושלמים, מילוי מים מסוננים וריקון תא הקפסולות.', '[{"step": 1, "title": "בדיקת מים מסוננים במיכל", "proTip": "אין להשתמש במי ברז רגילים – מים מסוננים שומרים על ארומת הקפה המקורית.", "instructions": "וודאו שמיכל המים האחורי מלא במים מתמי 4 או מים מינרליים לפחות עד קו החצי.", "illustrationUrl": "https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=600&q=80"}, {"step": 2, "title": "הכנסת קפסולת הבוטיק", "proTip": "אם המנוף מרגיש קשה להורדה, וודאו שהקפסולה מונחת ישר ואל תפעילו כוח מופרז.", "instructions": "הרימו את מנוף הכסף כלפי מעלה עד הסוף, הניחו את קפסולת הקפה בחריץ והורידו את המנוף.", "illustrationUrl": "https://images.unsplash.com/photo-1517668808822-9ebb02f2a0e6?auto=format&fit=crop&w=600&q=80"}, {"step": 3, "title": "בחירת כוס אספרסו או לונגו", "proTip": "לכוס גדולה, ניתן לקפל את מגש הטפטוף הקטן כלפי מעלה כדי להניח מאג גבוה.", "instructions": "הניחו כוס אספרסו או ספל ולחצו על הכפתור הקטן (אספרסו קצר) או הכפתור הגדול (לונגו ארוך).", "illustrationUrl": "https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=600&q=80"}, {"step": 4, "title": "הפלת הקפסולה בסיום", "proTip": "השארת קפסולה משומשת בתוך הראש עלולה לגרום לטפטוף – מומלץ להפיל אותה מיד לאחר המזיגה.", "instructions": "בסיום המזיגה, הרימו את המנוף והורידו שוב כדי להפיל את הקפסולה המשומשת למגירת האיסוף.", "illustrationUrl": "https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=600&q=80"}]', 'ran_and_kosta', true, '2026-09-10 05:57:14.179668+00')
ON CONFLICT (id) DO NOTHING;

