INSERT INTO public.b2b_deals VALUES
('3ab65699-3040-445d-95a0-bf62fbb78fa4', 'c9bd6850-ba53-46d6-a2b7-e2ccaac03fea', '20% הנחה על ערכות כלור וסינון + טיפול תקופתי שנתי', 'ערכת כימיקלים וסינון מלאה לשנה למערכות ספא ובריכות צימרים, כולל ביקורת טכנאי חצי-שנתית חינם.', 'hot_tubs_spa', 20, NULL, 'GOLANSPA20', 0, 5.00, false, NULL, NULL, true, '2026-09-10 05:57:13.460859+00'),
('d161c3df-b065-4ab6-aeb5-c14371e97c2c', 'c8303ba5-ae95-45e9-958a-02dbe4b6d0ed', '15% הנחת נפח על כביסת מצעים ומגבות פרימיום 500 גרם', 'שירות איסוף והחזרה יומי למתחמי אירוח ברמות, חד נס ונאות גולן. כולל גיהוץ ואריזה הרמטית.', 'laundry_linen', 15, NULL, 'LINENPRO15', 0, 5.00, true, NULL, NULL, true, '2026-09-10 05:57:13.661985+00'),
('d8d9caca-7525-4474-ac28-def1dc6c6660', '69564a6e-c4dc-41cb-8138-152a73e28bad', '₪300 הנחה על טיפול הכנה לחורף למשאבות חום בריכה', 'בדיקת גז, ניקוי מחליף חום, כיול תרמוסטטים וביקורת חשמל מקיפה לפני עונת החורף.', 'hvac_tech', NULL, 30000, 'HVACNORTH300', 0, 5.00, false, NULL, NULL, true, '2026-09-10 05:57:13.873641+00'),
('224f111b-40dd-44d5-9b87-1303ef9f68f3', '27c345cd-ea55-4d07-9cd9-16ea0e40bbc3', '25% הנחה על קרטוני קפסולות אלומיניום תואמות נספרסו', 'תערובות אספרסו 100% ערביקה טרייה בקלייה מקומית ברמת הגולן. ממותג בסטנדרט מלונאי יוקרתי.', 'coffee_tea', 25, NULL, 'GOLANICOFFEE25', 0, 5.00, true, NULL, NULL, true, '2026-09-10 05:57:14.085164+00')
